/**
 * frontend/src/components/Dashboard.jsx
 * VERSION ULTRA DEBUG - Pour identifier exactement le problème
 */

import React, { useState, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const Dashboard = ({ addNotification }) => {
  const [stats, setStats] = useState({});
  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [rawResponses, setRawResponses] = useState({});

  const loadData = async () => {
    try {
      setLoading(true);
      setError(null);

      const [studentRes, attendanceRes, logRes, statusRes] = await Promise.all([
        studentsAPI.getStats(),
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus(),
      ]);

      // Sauvegarde des réponses brutes pour debug
      const raw = {
        studentStats: studentRes,
        attendanceStats: attendanceRes,
        todayLog: logRes,
        status: statusRes,
      };
      setRawResponses(raw);

      console.log("=== RAW API RESPONSES ===", raw);

      // Extraction très sécurisée
      const studentData = studentRes?.data?.data || studentRes?.data || {};
      const attendanceData = attendanceRes?.data?.data || attendanceRes?.data || {};
      const logData = logRes?.data?.data?.records || logRes?.data?.records || logRes?.data || [];
      const statusData = statusRes?.data?.data?.students || statusRes?.data?.students || [];

      console.log("Extracted data →", { studentData, attendanceData, logDataLength: logData.length, statusDataLength: statusData.length });

      const active = Number(studentData.active_students) || 0;
      const presentToday = new Set(logData.map(r => r.student_id || r.id || r.student_id)).size;

      setStats({
        active_students: active,
        present_today: presentToday,
        absent_today: Math.max(0, active - presentToday),
        total_records: Number(attendanceData.total_records) || 0,
        avg_confidence: Number(attendanceData.avg_confidence) || 0,
        max_confidence: Number(attendanceData.max_confidence) || 0,
        min_confidence: Number(attendanceData.min_confidence) || 0,
      });

      setAttendanceLog(Array.isArray(logData) ? logData : []);
      setStatusList(Array.isArray(statusData) ? statusData : []);

    } catch (err) {
      console.error("Erreur loadData:", err);
      setError(err.message || "Erreur inconnue");
      if (addNotification) addNotification("Erreur chargement dashboard", "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleRefresh = () => loadData();

  if (loading) return <div style={{ padding: 40, textAlign: 'center' }}>Chargement...</div>;
  if (error) return <div style={{ padding: 40, color: 'red' }}>Erreur : {error}</div>;

  return (
    <div style={{ padding: '30px', fontFamily: 'Arial, sans-serif' }}>
      <h1>Dashboard - Mode Debug</h1>
      <button onClick={handleRefresh} style={{ padding: '10px 20px', marginBottom: '20px' }}>
        Rafraîchir
      </button>

      <h2>1. Réponses brutes de l'API (très important)</h2>
      <pre style={{ background: '#f4f4f4', padding: '15px', borderRadius: '8px', overflow: 'auto', maxHeight: '300px' }}>
        {JSON.stringify(rawResponses, null, 2)}
      </pre>

      <h2>2. Statistiques extraites</h2>
      <pre style={{ background: '#f4f4f4', padding: '15px', borderRadius: '8px' }}>
        {JSON.stringify(stats, null, 2)}
      </pre>

      <h2>3. Derniers scans ({attendanceLog.length} enregistrements)</h2>
      <pre style={{ background: '#f4f4f4', padding: '15px', borderRadius: '8px' }}>
        {JSON.stringify(attendanceLog.slice(0, 5), null, 2)}
      </pre>

      <h2>4. Liste des étudiants ({statusList.length} étudiants)</h2>
      <pre style={{ background: '#f4f4f4', padding: '15px', borderRadius: '8px' }}>
        {JSON.stringify(statusList.slice(0, 3), null, 2)}
      </pre>
    </div>
  );
};

export default Dashboard;
